 html+='</section><section class="panel"><div class="page-head"><div><h2 class="panel-title">Upcoming interviews</h2><p class="panel-subtitle">From your saved application interview schedules.</p></div><button class="btn btn-secondary btn-sm" data-pane="jobs">Manage schedule</button></div>';
 html+=d.upcomingInterviews?.length?'<div class="dashboard-upcoming-list">'+d.upcomingInterviews.map(x=>'<div class="list-row"><span class="list-icon">◷</span><div class="list-copy"><b>'+esc(x.title)+'</b><small>'+esc(x.company)+' · '+esc(x.job_title)+'</small><small>'+esc(dateTimeText(x.scheduled_at))+'</small></div></div>').join('')+'</div>':emptyState('No upcoming interviews','Add an interview date to the relevant application when the employer confirms a round.','Open Job Tracker','jobs');
