 if(cv.templateId==='fresher')rows=[rows[0],rows[1],rows[3],rows[4],rows[2],rows[5],rows[6]];
 if(cv.templateId==='developer')rows=[rows[0],rows[1],rows[3],rows[2],rows[4],rows[5],rows[6]];
 if(cv.templateId==='experienced')rows=[rows[0],rows[2],rows[6],rows[1],rows[3],rows[4],rows[5]];
 if(cv.templateId==='leadership')rows=[rows[0],rows[2],rows[6],rows[1],rows[3],rows[4],rows[5]];
