async function extractCareerDocument(file){
 if(!file)throw Error('Choose a file first.');
 if(file.size>12*1024*1024)throw Error('Files must be 12 MB or smaller.');
 const name=String(file.name||'document'),ext=(name.split('.').pop()||'').toLowerCase();let result='';
 if(ext==='pdf'){
  if(!window.pdfjsLib)throw Error('PDF extraction library did not load. Refresh and retry, or paste the text.');
  const pdf=await window.pdfjsLib.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;
  if(pdf.numPages>60)throw Error('This PDF has more than 60 pages. Please split it or paste the relevant sections.');
  const pages=[];for(let n=1;n<=pdf.numPages;n++){const page=await pdf.getPage(n),content=await page.getTextContent();pages.push(content.items.map(x=>x.str||'').join(' '))}
  result=pages.join('\n\n');
 }else if(ext==='docx'){
  if(!window.mammoth)throw Error('DOCX extraction library did not load. Refresh and retry, or paste the text.');
  const extracted=await window.mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()});result=extracted.value||'';
 }else if(['txt','md','csv','json','html','htm'].includes(ext)){
  result=await file.text();if(ext==='html'||ext==='htm')result=result.replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<br\s*\/?\s*>/gi,'\n').replace(/<\/(p|div|li|h[1-6])>/gi,'\n').replace(/<[^>]+>/g,' ').replace(/&nbsp;/gi,' ').replace(/&amp;/gi,'&').replace(/&quot;/gi,'"').replace(/&lt;/gi,'<').replace(/&gt;/gi,'>');
 }else throw Error('Supported files: PDF, DOCX, TXT, Markdown, CSV, JSON, or HTML.');
 result=String(result).replace(/\u0000/g,'').replace(/[ \t]+/g,' ').replace(/\n{3,}/g,'\n\n').trim();
 if(result.length<60)throw Error(ext==='pdf'?'No selectable text was found in this PDF. It may be scanned; paste the text or use a text-based copy.':'Very little text could be extracted. Please review or paste the text manually.');
 return result.slice(0,30000);
}
