function interviewEvaluationMarkup(e){
 if(!e||typeof e!=='object')return '<p class="small-note">No structured feedback was saved for this answer.</p>';
 const dims=[['correctness','Correctness'],['communication','Communication'],['problemSolving','Problem solving'],['complexity','Complexity analysis'],['edgeCases','Edge cases'],['tradeoffs','Trade-offs']];
 const scores=e.dimensionScores&&typeof e.dimensionScores==='object'?e.dimensionScores:{};
 const scoreCards=dims.filter(x=>Number.isFinite(Number(scores[x[0]]))).map(x=>'<div class="interview-score-card"><span>'+esc(x[1])+'</span><b>'+Math.max(0,Math.min(100,Number(scores[x[0]])))+'</b><i><em style="width:'+Math.max(0,Math.min(100,Number(scores[x[0]])))+'%"></em></i></div>').join('');
 const list=(label,items)=>Array.isArray(items)&&items.length?'<section class="interview-feedback-section"><h5>'+esc(label)+'</h5><ul>'+items.map(x=>'<li>'+esc(typeof x==='string'?x:JSON.stringify(x))+'</li>').join('')+'</ul></section>':'';
 return '<div class="interview-feedback"><div class="interview-feedback-overall"><b>Coaching score: '+(Number.isFinite(Number(e.score))?Math.max(0,Math.min(100,Number(e.score)))+'/100':'Not scored')+'</b><span>Indicative practice feedback, not a hiring result.</span></div>'+(scoreCards?'<div class="interview-score-grid">'+scoreCards+'</div>':'')+(e.correctness?'<p><b>Correctness:</b> '+esc(e.correctness)+'</p>':'')+(e.communication?'<p><b>Communication:</b> '+esc(e.communication)+'</p>':'')+(e.problemSolving?'<p><b>Problem solving:</b> '+esc(e.problemSolving)+'</p>':'')+list('Strengths',e.strengths)+list('Improvements',e.improvements)+list('Complexity, edge cases and trade-offs to review',e.missingEvidence)+list('Suggested answer outline',e.suggestedAnswerOutline)+list('Practice next',e.practicePlan)+(e.nextDifficulty?'<p class="small-note">Suggested next difficulty: <b>'+esc(e.nextDifficulty)+'</b></p>':'')+'</div>';
}
