async function initCompilerEditor(root){
 const ta=root.querySelector('#compilerSourceCode');if(!ta)return;
 const addCss=(href)=>{if(!document.querySelector('link[data-compiler-css="'+href+'"]')){const l=document.createElement('link');l.rel='stylesheet';l.href=href;l.dataset.compilerCss=href;document.head.appendChild(l)}};
 const loadScript=(src)=>new Promise((resolve,reject)=>{if(document.querySelector('script[data-compiler-script="'+src+'"]'))return resolve();const s=document.createElement('script');s.src=src;s.async=true;s.dataset.compilerScript=src;s.onload=resolve;s.onerror=reject;document.head.appendChild(s)});
 try{
  addCss('https://cdnjs.cloudflare.com/ajax/libs/codemirror/5.65.16/codemirror.min.css');
  if(!window.CodeMirror)await loadScript('https://cdnjs.cloudflare.com/ajax/libs/codemirror/5.65.16/codemirror.min.js');
  const lang=state.editorLanguage||'cpp';
  const mode=({cpp:'text/x-c++src',c:'text/x-csrc',java:'text/x-java',python:'python',javascript:'javascript',typescript:'javascript',go:'text/x-go',rust:'text/x-rustsrc',csharp:'text/x-csharp',ruby:'ruby',php:'application/x-httpd-php',kotlin:'text/x-kotlin'}[lang]||'text/x-c++src');
  const modeFile=({cpp:'clike/clike',c:'clike/clike',java:'clike/clike',csharp:'clike/clike',kotlin:'clike/clike',python:'python/python',javascript:'javascript/javascript',typescript:'javascript/javascript',go:'go/go',rust:'rust/rust',ruby:'ruby/ruby',php:'php/php'}[lang]||'clike/clike');
  try{await loadScript('https://cdnjs.cloudflare.com/ajax/libs/codemirror/5.65.16/mode/'+modeFile+'.min.js')}catch(e){try{await loadScript('https://cdnjs.cloudflare.com/ajax/libs/codemirror/5.65.16/mode/'+modeFile+'.js')}catch(e2){}}
  if(root.querySelector('#compilerSourceCode')!==ta||state.codeMirror)return;
  if(document.documentElement.dataset.theme==='dark')addCss('https://cdnjs.cloudflare.com/ajax/libs/codemirror/5.65.16/theme/material-darker.min.css');
  state.codeMirror=window.CodeMirror.fromTextArea(ta,{mode,theme:document.documentElement.dataset.theme==='dark'?'material-darker':'default',lineNumbers:true,indentUnit:4,tabSize:4,indentWithTabs:false,lineWrapping:false,matchBrackets:true,viewportMargin:20,extraKeys:{'Ctrl-Enter':runCompiler,'Cmd-Enter':runCompiler,'Tab':'indentMore'}});
  state.codeMirror.setSize('100%',460);
  state.codeMirror.on('change',editor=>{state.editorCode=editor.getValue()});
 }catch(e){const note=root.querySelector('.compiler-editor-title small');if(note)note.textContent='Plain text fallback · editor library unavailable'}
}

function localDateTimeValue(date){
 const d=date instanceof Date?date:new Date(date),pad=n=>String(n).padStart(2,'0');
 return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())+'T'+pad(d.getHours())+':'+pad(d.getMinutes());
}
