function dateTimeText(v){if(!v)return 'No date set';const d=new Date(v);return Number.isNaN(d.getTime())?'Invalid date':d.toLocaleString([], {dateStyle:'medium',timeStyle:'short'})}
async function processBrowserNotifications(data,notify){
 const p=data&&data.preferences;
 if(!p||!p.browser_notifications_enabled||!('Notification' in window)||Notification.permission!=='granted')return;
 const items=data.notifications||[],max=items.reduce((m,x)=>Math.max(m,Number(x.id)||0),0);
 let last=0,initialized=false;
 try{const v=localStorage.getItem('careeros-browser-notification-last');initialized=v!==null;last=Number(v)||0}catch(e){}
 const fresh=initialized&&notify?items.filter(x=>!x.read_at&&Number(x.id)>last).sort((a,b)=>Number(a.id)-Number(b.id)):[];
 for(const n of fresh.slice(-5)){
  try{const note=new Notification(n.title,{body:n.body,icon:'/icon.svg',tag:'careeros-'+n.id});note.onclick=()=>{window.focus();renderPane('notifications')}}
  catch(e){console.warn('Browser notification unavailable',e)}
 }
 try{if(max>last||!initialized)localStorage.setItem('careeros-browser-notification-last',String(Math.max(max,last)))}catch(e){}
}
async function pollBrowserNotifications(notify=true){
 if(!state.user)return;
 try{const d=await api('/notifications');await processBrowserNotifications(d,notify);const n=Number(d.counts?.unread||0),badge=$('#notificationNavBadge');if(badge){badge.textContent=n>99?'99+':String(n);badge.classList.toggle('hidden',n===0)}}
 catch(e){console.warn('Notification poll unavailable',e)}
}
function startNotificationPolling(){
 if(state.notificationPollTimer)return;
 pollBrowserNotifications(false);
 state.notificationPollTimer=setInterval(()=>{if(state.user)pollBrowserNotifications(true)},5*60*1000);
}

async function extractResearchFile(file){
 if(!file)throw new Error('Choose a file first.');
 if(file.size>10*1024*1024)throw new Error('Choose a file smaller than 10 MB.');
 const name=String(file.name||'').toLowerCase(),buffer=await file.arrayBuffer();
 if(name.endsWith('.pdf')){
  if(!window.pdfjsLib||typeof window.pdfjsLib.getDocument!=='function')throw new Error('The PDF text extractor could not load. Paste text from the document instead.');
  const doc=await window.pdfjsLib.getDocument({data:new Uint8Array(buffer)}).promise;
  const chunks=[],maxPages=Math.min(doc.numPages,35);let length=0;
  for(let i=1;i<=maxPages&&length<16000;i++){
   const page=await doc.getPage(i),data=await page.getTextContent(),line=data.items.map(x=>x.str||'').join(' ');
   chunks.push(line);length+=line.length;
  }
  if(doc.numPages>maxPages)toast('Extracted the first '+maxPages+' pages to keep the source within limits.');
  return {sourceType:'pdf',text:chunks.join('\n\n').slice(0,16000),pages:doc.numPages};
 }
 if(name.endsWith('.docx')){
  if(!window.mammoth||typeof window.mammoth.extractRawText!=='function')throw new Error('The DOCX text extractor could not load. Paste text from the document instead.');
  const result=await window.mammoth.extractRawText({arrayBuffer:buffer});
  return {sourceType:'docx',text:String(result.value||'').slice(0,16000),pages:null};
 }
 if(name.endsWith('.md')||name.endsWith('.markdown'))return {sourceType:'markdown',text:(await file.text()).slice(0,16000),pages:null};
 if(name.endsWith('.txt')||file.type==='text/plain')return {sourceType:'text',text:(await file.text()).slice(0,16000),pages:null};
 throw new Error('Supported uploads are PDF, DOCX, Markdown and plain-text files.');
}

function researchNoteMarkdown(note){
 const out=['# '+String(note.title||'Research notes'),'','Source type: '+String(note.source_type||'topic')];
 if(note.source_url)out.push('Source: '+note.source_url);
 out.push('Updated: '+String(note.updated_at||note.created_at||''),'','## Summary',String(note.summary||''),'');
 const fence=String.fromCharCode(96).repeat(3);
 const concepts=Array.isArray(note.key_concepts)?note.key_concepts:[];
 if(concepts.length){out.push('## Key concepts','');concepts.forEach(x=>out.push('### '+String(x.concept||''),String(x.detail||''),''))}
 const examples=Array.isArray(note.examples)?note.examples:[];
 if(examples.length){out.push('## Examples','');examples.forEach(x=>out.push('### '+String(x.title||'Example'),String(x.description||''),''))}
 const snippets=Array.isArray(note.code_snippets)?note.code_snippets:[];
 if(snippets.length){out.push('## Code snippets','');snippets.forEach(x=>out.push('### '+String(x.language||'text'),fence+String(x.language||'text'),String(x.code||''),fence,String(x.explanation||''),''))}
 const questions=Array.isArray(note.interview_questions)?note.interview_questions:[];
 if(questions.length){out.push('## Interview questions','');questions.forEach(x=>out.push('- '+String(x.question||''),x.answerOutline?'  - Answer outline: '+x.answerOutline:'',''))}
 const checklist=Array.isArray(note.revision_checklist)?note.revision_checklist:[];
 if(checklist.length){out.push('## Revision checklist','');checklist.forEach(x=>out.push('- [ ] '+String(x)));out.push('')}
 out.push('## My notes','',String(note.editable_notes||''),'');
 if(Array.isArray(note.source_citations)&&note.source_citations.length){out.push('## Sources','');note.source_citations.forEach(x=>out.push('- '+String(x.label||x.url||'Source')+(x.url?' — '+x.url:'')))}
 out.push('## Tags','',(Array.isArray(note.tags)?note.tags:[]).join(', '));
 return out.join('\n');
}
function exportResearchNote(note){
 const blob=new Blob([researchNoteMarkdown(note)],{type:'text/markdown;charset=utf-8'});
 const url=URL.createObjectURL(blob),a=document.createElement('a');
 a.href=url;a.download=(String(note.title||'research-notes').replace(/[^a-z0-9_-]+/gi,'-').replace(/^-+|-+$/g,'')||'research-notes')+'.md';
 document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);
}
