 html+=upcoming.length?'<div class="upcoming-interview-grid">'+upcoming.map(x=>'<article class="upcoming-interview-item"><span class="badge">'+esc(x.format||'interview')+'</span><h3>'+esc(x.title)+'</h3><p><b>'+esc(x.company)+'</b> · '+esc(x.job_title)+'</p><p>'+esc(dateTimeText(x.scheduled_at))+'</p>'+(x.location_or_link?'<a class="link-quiet" target="_blank" rel="noopener noreferrer" href="'+esc(/^https?:\/\//i.test(x.location_or_link)?x.location_or_link:'#')+'">Meeting link / location ↗</a>':'')+'<button class="btn btn-secondary btn-sm" data-pane="interviews">Open mock interview practice</button></article>').join('')+'</div>':emptyState('No upcoming interview schedules','When an employer confirms a round, add it to the matching application to keep its date and reminder in one place.');
