async function renderOpportunities(){
 const f=state.opportunityFilters||{q:'',location:'',stage:'any'};
 let html=pageHead('LIVE JOB DISCOVERY','Find real opportunities.','Listings are fetched from live third-party job feeds. Open the publisher’s page to confirm eligibility and apply.','<button class="btn btn-secondary" id="refreshOpportunities">↻ Refresh feed</button>');
 html+='<section class="panel"><form id="opportunitySearchForm" class="form-grid"><div class="field"><label for="opportunityQuery">Role, skill or company</label><input id="opportunityQuery" maxlength="100" placeholder="e.g. backend engineer, product, design" value="'+esc(f.q||'')+'"></div><div class="field"><label for="opportunityLocation">Location or remote</label><input id="opportunityLocation" maxlength="100" placeholder="e.g. India, Ahmedabad, remote" value="'+esc(f.location||'')+'"></div><div class="field"><label for="opportunityStage">Best fit</label><select id="opportunityStage"><option value="any" '+(f.stage==='any'?'selected':'')+'>All career stages</option><option value="student" '+(f.stage==='student'?'selected':'')+'>Student / early career</option><option value="professional" '+(f.stage==='professional'?'selected':'')+'>Working professional</option><option value="entrepreneur" '+(f.stage==='entrepreneur'?'selected':'')+'>Freelance / startup / growth</option></select></div><div class="field" style="align-self:end"><button class="btn btn-primary" type="submit">Search live jobs ↗</button></div></form><p class="small-note">Sources: Himalayas, Jobicy and Remotive public feeds. Feeds may focus on remote roles; no listing is guaranteed to remain open.</p></section>';
 html+='<section id="opportunityResults" class="panel" style="margin-top:15px"><div class="loading-block large"></div></section>';
 const params=new URLSearchParams({limit:'60',stage:f.stage||'any'});
 if(f.q)params.set('q',f.q);if(f.location)params.set('location',f.location);
 try{
  const d=await api('/jobs?'+params.toString());
  state.opportunities=d.jobs||[];
  const el=$('#opportunityResults');
  if(!el)return html;
  const sourceHtml=(d.sources||[]).map(s=>'<span class="badge '+(s.status==='live'?'good':'warn')+'">'+esc(s.name)+': '+esc(s.status)+(s.count!=null?' · '+Number(s.count):'')+'</span>').join(' ');
  let body='<div class="page-head"><div><div class="tiny-label">LIVE FEED · '+Number(d.total||0)+' MATCHES</div><h2 class="panel-title">Current listings</h2><p class="panel-subtitle">Fetched '+esc(d.fetchedAt?new Date(d.fetchedAt).toLocaleString():'just now')+'</p></div><div class="page-actions">'+sourceHtml+'</div></div>';
  if(d.error)body+='<div class="notice"><span>!</span><div>'+esc(d.error)+'</div></div>';
  else if(!state.opportunities.length)body+=emptyState('No live listings match these filters','Change your search terms or location. No placeholder jobs are inserted.');
  else body+='<div class="topic-grid">'+state.opportunities.map((j,i)=>'<article class="topic-card"><div class="topic-top"><span>'+esc(j.source||'External source')+'</span><span class="badge">'+esc(j.employmentType||'Role')+'</span></div><h3>'+esc(j.title)+'</h3><p><b>'+esc(j.company)+'</b> · '+esc(j.location||'Location not stated')+'</p><p>'+esc(j.description||'The publisher has not supplied a summary.')+'</p><div class="topic-top"><span>'+esc(j.salary||'Salary not provided')+'</span><span>'+esc(j.seniority||'Seniority not stated')+'</span></div><small class="small-note">'+(j.publishedAt?'Published '+esc(dateText(j.publishedAt)):'Publication date not provided')+'</small><div class="form-actions"><a class="btn btn-primary btn-sm" target="_blank" rel="noopener noreferrer" href="'+esc(j.applyUrl||j.jobUrl||j.sourceUrl)+'">View & apply ↗</a><button class="btn btn-secondary btn-sm" data-track-job="'+i+'">Track this role</button></div></article>').join('')+'</div>';
  body+='<p class="small-note">'+esc(d.disclaimer||'Listings come from third-party sources. Confirm details before applying.')+'</p>';
  el.innerHTML=body;
 }catch(e){
  state.opportunities=[];
  const el=$('#opportunityResults');
  if(el)el.innerHTML='<div class="notice"><span>!</span><div>'+esc(e.message||'Live job feeds are unavailable right now. Retry later; no dummy listings are shown.')+'</div></div>';
 }
 return html;
}
function planSection(title, items){
 if(!Array.isArray(items)||!items.length)return '';
 return '<section style="margin-top:14px"><h3>'+esc(title)+'</h3><ul class="result-list">'+items.map(x=>'<li>'+esc(typeof x==='string'?x:x&&typeof x==='object'?Object.entries(x).map(([k,v])=>k.replaceAll(/([A-Z])/g,' $1')+': '+(Array.isArray(v)?v.join(', '):String(v??''))).join(' — '):String(x??''))+'</li>').join('')+'</ul></section>';
}
