 const resumeText=[savedCv?.raw_text,cvData.summary,cvData.skills,cvData.experience,cvData.projects,cvData.headline].filter(Boolean).join(' ').toLowerCase();
 const knownSkillPhrases=['node.js','nodejs','typescript','javascript','nestjs','nest.js','mongodb','mongoose','postgresql','mysql','redis','bullmq','rxjs','rest api','graphql','docker','kubernetes','aws','microservices','system design','react','java','python','sql','terraform','websocket','websockets','kafka','rabbitmq','ci/cd','git'];
