 html+='<section class="panel job-portal-panel"><div class="page-head"><div><h2 class="panel-title">More job-search portals</h2><p class="panel-subtitle">These open external searches, not imported or verified individual listings. Confirm the employer, posting date and original application link on the publisher page.</p></div></div><div class="job-portal-links">'+(d.portalSearches||[]).map(x=>'<a class="job-portal-link" href="'+esc(x.url)+'" target="_blank" rel="noopener noreferrer"><b>'+esc(x.name)+'</b><span>'+esc(x.kind||'External search')+'</span><small>Open search ↗</small></a>').join('')+'</div><p class="small-note">Google Search, LinkedIn, Naukri and Wellfound are linked as external search portals. CareerOS does not scrape restricted pages or claim their results are verified.</p></section>';
