async function saveProfile(e){
 e.preventDefault();
 const form=e.currentTarget,msg=$('#profileFormMsg'),btn=form.querySelector('button[type="submit"]');
 if(btn)btn.disabled=true;
 msg.textContent='Saving your profile…';msg.classList.remove('error');
 const split=id=>$('#'+id).value.split(',').map(x=>x.trim()).filter(Boolean);
 const payload={fullName:$('#profileName').value,profileHeadline:$('#profileHeadline').value,bio:$('#profileBio').value,websiteUrl:$('#profileWebsite').value,linkedinUrl:$('#profileLinkedin').value,githubUrl:$('#profileGithub').value,careerStage:$('#careerStage').value,currentRole:$('#currentRole').value,experienceYears:$('#experienceYears').value,targetRole:$('#targetRole').value,currentSkills:split('currentSkills'),education:$('#education').value,preferredLocation:$('#preferredLocation').value,workPreference:$('#workPreference').value,targetDate:$('#targetDate').value||null,weeklyHours:$('#weeklyHours').value,learningStyle:$('#learningStyle').value,strengths:split('strengths'),challengeAreas:split('challengeAreas'),targetCompanies:split('targetCompanies'),certifications:split('certifications'),salaryExpectationInr:$('#salaryExpectationInr').value||null};
 try{
  const saved=await api('/profile',{method:'POST',body:payload});
  const check=await api('/profile');
  if(!check.profile||String(check.profile.id)!==String(saved.profile?.id)||String(check.profile.target_role||'')!==String(payload.targetRole||'').trim())throw Error('The save request returned, but the profile could not be verified after reloading. Please retry.');
  state.profile=check.profile;state.profileEditMode=false;
  const name=check.profile.full_name||state.user?.name||'C';
  if($('#userLabel'))$('#userLabel').textContent=check.profile.full_name||'My CareerOS';
  if($('#userInitial'))$('#userInitial').textContent=name.slice(0,1).toUpperCase();
  if($('#sideUserAvatar'))$('#sideUserAvatar').textContent=name.slice(0,1).toUpperCase();
  if($('#sideEmail'))$('#sideEmail').textContent=String(state.user?.email||'Signed in');
  msg.textContent='Verified: your profile was saved and reloaded from career_profiles.';
  toast('Profile saved and verified · record #'+check.profile.id);
  await renderPane('profile');
 }catch(err){msg.textContent=err.message;msg.classList.add('error');toast(err.message,true)}
 finally{if(btn)btn.disabled=false}
}
function clientCvPlainText(cv){
 const out=[];
 if(cv.fullName)out.push(cv.fullName.toUpperCase());
 if(cv.headline)out.push(cv.headline);
 out.push([cv.email,cv.phone,cv.location,cv.website,cv.linkedin,cv.github].filter(Boolean).join(' | '),'');
 for(const [heading,value] of cvSections(cv)){out.push(heading,value,'')}
 return out.join('\n').trim();
}
async function persistCv(runAts){
 const form=$('#cvBuilderForm'),msg=$('#cvBuilderMsg');
 if(!form||!msg)return;
 const button=$(runAts?'#runCvAts':'#saveCvBtn'),data=collectCvFormData(form),jobDescription=$('#cvJobDescription')?.value||'';
 if(button)button.disabled=true;
 msg.textContent=runAts?'Running free ATS checklist…':'Saving CV…';msg.classList.remove('error');
 try{
  const result=await api('/cv-builder',{method:'POST',body:{action:runAts?'ats-check':'save-cv',cvData:data,jobDescription}});
  state.cvCurrentData=result.cv?.cv_data||data;
  state.cvAtsReport=result.report||result.cv?.ats_report||null;
  const updated=result.cv?.updated_at;
  msg.textContent=(result.message||'Done.')+(updated?' Saved '+dateTimeText(updated)+'.':'');
  toast(runAts?'Free ATS check complete':'CV saved');
  const preview=$('#cvPreview');if(preview)preview.innerHTML=cvPreviewMarkup(state.cvCurrentData);
  const report=$('#cvAtsReportBody');if(report&&runAts)report.innerHTML=cvAtsReportMarkup(state.cvAtsReport);
 }catch(err){msg.textContent=err.message||'Could not save the CV.';msg.classList.add('error');toast(msg.textContent,true)}
 finally{if(button)button.disabled=false}
}
function exportCvPdf(){
 const cv=collectCvFormData($('#cvBuilderForm'));
 const preview=$('#cvPreview');if(preview)preview.innerHTML=cvPreviewMarkup(cv);
 window.print();
}
async function exportCvWord(){
 const cv=collectCvFormData($('#cvBuilderForm')),lib=window.docx;
 const base=(cv.fullName||'CareerOS-CV').trim().replace(/[^a-z0-9_-]+/gi,'-').replace(/^-+|-+$/g,'')||'CareerOS-CV';
 if(!lib||!lib.Document||!lib.Packer||!lib.Paragraph||!lib.TextRun){toast('DOCX library could not load. Use Export PDF or retry after refreshing.',true);return}
 const accent={navy:'273858',blue:'315FBE',teal:'147D79',plum:'714A85',charcoal:'374151'}[cv.accentColor]||'273858';
 const children=[];
 children.push(new lib.Paragraph({alignment:lib.AlignmentType?.CENTER,spacing:{after:120},children:[new lib.TextRun({text:cv.fullName||'Your Name',bold:true,size:34,color:accent,font:cv.fontStyle==='serif'?'Georgia':'Arial'})]}));
 if(cv.headline)children.push(new lib.Paragraph({alignment:lib.AlignmentType?.CENTER,spacing:{after:100},children:[new lib.TextRun({text:cv.headline,bold:true,size:24,color:'425470'})]}));
 const contacts=[cv.email,cv.phone,cv.location,cv.website,cv.linkedin,cv.github].filter(Boolean);
 if(contacts.length)children.push(new lib.Paragraph({alignment:lib.AlignmentType?.CENTER,spacing:{after:260},children:[new lib.TextRun({text:contacts.join('  |  '),size:18,color:'536176'})]}));
 for(const [heading,content] of cvSections(cv)){
  children.push(new lib.Paragraph({heading:lib.HeadingLevel?.HEADING_2,spacing:{before:240,after:100},border:{bottom:{style:lib.BorderStyle?.SINGLE||'single',size:5,color:accent,space:4}},children:[new lib.TextRun({text:heading,bold:true,size:22,color:accent,font:'Arial'})]}));
  String(content||'').split(/\r?\n/).forEach(line=>{const trimmed=line.trim();if(!trimmed)return;const bullet=/^[-*•]\s+/.test(trimmed);children.push(new lib.Paragraph({bullet:bullet?{indent:260}:undefined,spacing:{after:65},children:[new lib.TextRun({text:trimmed.replace(/^[-*•]\s+/,''),size:20,font:cv.fontStyle==='serif'?'Georgia':'Arial'})]}))});
 }
 try{const doc=new lib.Document({sections:[{properties:{page:{margin:{top:850,right:900,bottom:850,left:900}}},children}]});const blob=await lib.Packer.toBlob(doc);const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=base+'.docx';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('DOCX resume downloaded')}catch(e){console.error('DOCX export failed',e);toast('Could not create the DOCX file. Try PDF export.',true)}
}
