function renderCoachAttachments(){const input=$('#coachFiles'),list=$('#coachAttachmentList');if(!input||!list)return;const files=Array.from(input.files||[]);list.innerHTML=files.map((f,i)=>'<div class="coach-attachment"><span>▤</span><span>'+esc(f.name)+' · '+Math.ceil(f.size/1024)+' KB</span><button type="button" data-remove-file="'+i+'" aria-label="Remove '+esc(f.name)+'">×</button></div>').join('');list.querySelectorAll('[data-remove-file]').forEach(b=>b.onclick=()=>{const dt=new DataTransfer();Array.from(input.files||[]).forEach((f,i)=>{if(i!==Number(b.dataset.removeFile))dt.items.add(f)});input.files=dt.files;renderCoachAttachments()})}
async function readCoachAttachments(){const files=Array.from($('#coachFiles')?.files||[]);if(files.length>4)throw Error('Attach up to 4 files per message.');let out=[];for(const f of files){if(f.size>180000)throw Error('Each attachment must be under 180 KB.');if(!/\.(txt|md|csv|json|js|ts|tsx|jsx|py|java|sql|html|css)$/i.test(f.name))throw Error('For now, attach text, Markdown, CSV, JSON or source-code files. PDF/DOCX extraction is not enabled yet.');const content=await f.text();out.push({name:f.name,content:content.slice(0,24000)})}return out}
async function createRoadmap(e){e.preventDefault();const msg=$('#roadmapFormMsg'),btn=e.submitter;if(btn)btn.disabled=true;try{const durationType=$('#roadmapDurationType')?.value||'30';let days=durationType==='custom'?Number($('#roadmapCustomDays')?.value||30):Number(durationType);days=Math.max(7,Math.min(365,Math.trunc(days)));const d=await api('/roadmaps',{method:'POST',body:{title:$('#roadmapTitle').value,targetRole:$('#roadmapRole').value,weeks:Math.ceil(days/7),days,weeklyHours:$('#roadmapHours').value,goalId:$('#roadmapGoal').value||null,targetDate:$('#roadmapDate').value||null,useAI:$('#roadmapAi').value==='true'}});toast(d.message||'Roadmap created');await renderPane('roadmap')}catch(err){msg.textContent=err.message;msg.classList.add('error')}finally{if(btn)btn.disabled=false}}
async function createConversation(){try{const d=await api('/conversations',{method:'POST',body:{title:'New conversation',contextType:'career_coach'}});state.activeConversationId=Number(d.conversation.id);await renderPane('coach');$('#coachPrompt')?.focus()}catch(e){toast(e.message,true)}}
async function sendCoach(e){e.preventDefault();const form=$('#coachForm'),prompt=$('#coachPrompt'),msg=$('#coachMsg'),btn=$('#coachSendBtn'),stop=$('#coachStopBtn');const typed=prompt.value.trim();let attachments=[];try{attachments=await readCoachAttachments()}catch(err){msg.textContent=err.message;msg.classList.add('error');return}if(!typed&&!attachments.length)return;const userText=typed+(attachments.length?'\n\nAttached document excerpts:\n'+attachments.map(f=>'--- '+f.name+' ---\n'+f.content).join('\n\n'):'');if(userText.length>30000){msg.textContent='This message is too large. Shorten the prompt or attachment contents.';msg.classList.add('error');return}btn.disabled=true;if(stop)stop.classList.remove('hidden');msg.textContent='CareerOS is thinking…';msg.classList.remove('error');let id=state.activeConversationId;state.coachController=new AbortController();try{if(!id){const c=await api('/conversations',{method:'POST',body:{title:(typed||attachments[0]?.name||'Document question').slice(0,64),contextType:'career_coach'}});id=Number(c.conversation.id);state.activeConversationId=id}const d=await api('/coach',{method:'POST',signal:state.coachController.signal,body:{conversationId:id,prompt:userText}});state.coachLastPrompt=userText;prompt.value='';if($('#coachFiles'))$('#coachFiles').value='';toast('Response saved to your conversation');await renderPane('coach')}catch(err){if(err.name==='AbortError'){msg.textContent='Stopped waiting for this response. If the provider already completed, it may still be saved; refresh the conversation to check.'}else{msg.textContent=err.message;msg.classList.add('error');const retry=document.createElement('button');retry.type='button';retry.className='btn btn-secondary btn-sm';retry.textContent='Retry';retry.onclick=()=>{prompt.value=typed;form.requestSubmit()};msg.appendChild(retry)}}finally{state.coachController=null;if($('#coachSendBtn'))$('#coachSendBtn').disabled=false;if($('#coachStopBtn'))$('#coachStopBtn').classList.add('hidden')}}
function stopCoachGeneration(){if(state.coachController){state.coachController.abort();state.coachController=null}}
async function regenerateCoachMessage(index){const messages=Array.from(document.querySelectorAll('#chatMessages .coach-message'));const msg=messages[index];if(!msg)return;const prev=msg.previousElementSibling;if(!prev||!prev.classList.contains('user')){toast('Cannot find the original prompt for this response.',true);return}const text=prev.querySelector('.coach-message-content')?.innerText||'';const prompt=$('#coachPrompt');if(prompt){prompt.value=text;toast('Regenerating a fresh answer…');$('#coachForm')?.requestSubmit()}}
// The canonical Resume Studio workflow is renderResume + persistCv; legacy duplicate resume form handlers were removed.
function analysisItemText(x){if(x==null)return '';if(typeof x==='string'||typeof x==='number')return String(x);return String(x.skill||x.keyword||x.requirement||x.topic||x.title||x.responsibility||x.name||x.description||x.suggestion||JSON.stringify(x))}
function analysisSectionHtml(title,items,subtext){if(!Array.isArray(items)||!items.length)return '';return '<section class="job-report-section"><h3>'+esc(title)+'</h3>'+(subtext?'<p class="small-note">'+esc(subtext)+'</p>':'')+'<ul>'+items.map(x=>{if(x&&typeof x==='object'){const primary=analysisItemText(x),meta=[x.importance,x.priority,x.confidence,x.yearsOrLevel].filter(Boolean).join(' · '),extra=x.resumeEvidence||x.evidenceFromDescription||x.reason||x.why||x.status||'';return '<li><div><b>'+esc(primary)+'</b>'+(meta?'<span class="job-report-meta">'+esc(meta)+'</span>':'')+(extra?'<p>'+esc(extra)+'</p>':'')+(x.needsCandidateConfirmation?'<small>Confirm this with your own experience before treating it as a real skill gap.</small>':'')+'</div></li>'}return '<li>'+esc(analysisItemText(x))+'</li>'}).join('')+'</ul></section>'}
function renderJobAnalysisReport(a,disclaimer){a=a||{};const required=Array.isArray(a.requiredSkills)?a.requiredSkills:[],preferred=Array.isArray(a.preferredSkills)?a.preferredSkills:[],keywords=Array.isArray(a.keywords)?a.keywords:[],evidenceLabel={present_in_resume:'Evidence in resume',profile_only:'In profile, not shown in resume',not_evidenced:'Not evidenced in supplied sources'};let html='<div class="job-report-summary"><div><span class="tiny-label">ROLE SUMMARY</span><p>'+esc(a.roleSummary||'Review the skill and evidence sections below. Separate source requirements from candidate claims.')+'</p></div><div class="job-report-level"><small>Seniority</small><b>'+esc(a.seniority||'Not specified')+'</b></div></div><div class="job-evidence-legend"><span class="job-evidence-present">Evidence in resume</span><span class="job-evidence-profile">Profile only</span><span class="job-evidence-missing">Not evidenced</span></div>';
 html+=analysisSectionHtml('Required skills',required,'Skills explicitly marked required in the posting.');
 html+=analysisSectionHtml('Preferred skills',preferred,'Preferred or bonus skills, not necessarily hard requirements.');
 html+=analysisSectionHtml('Experience requirements',a.experienceRequirements,'Extracted seniority, years or level requirements.');
 html+=analysisSectionHtml('Responsibilities',a.responsibilities);
 html+=analysisSectionHtml('Strengths supported by your sources',Array.isArray(a.strengths)&&a.strengths.length?a.strengths:a.alreadyDemonstrated,'AI-assisted matches to your provided profile/resume; verify details.');
 html+=analysisSectionHtml('Keywords and evidence status',keywords.map(x=>({...x,evidenceStatusLabel:evidenceLabel[x.evidenceStatus]||x.evidenceStatus})).map(x=>({...x,importance:(x.importance||'')+' · '+(x.evidenceStatusLabel||''),resumeEvidence:x.resumeEvidence||x.evidenceFromDescription||''})),'A keyword absent from the resume may still be a real skill. “Not evidenced” is not proof that you lack it.');
 html+=analysisSectionHtml('Missing or unproven keywords to review',keywords.filter(x=>x&&x.evidenceStatus!=='present_in_resume').map(x=>({...x,importance:(x.importance||'')+' · '+(evidenceLabel[x.evidenceStatus]||x.evidenceStatus||''),resumeEvidence:x.resumeEvidence||x.evidenceFromDescription||''})),'These keywords were not clearly present in the resume. Some may be supported by your profile or real experience; verify before adding them.');
 html+=analysisSectionHtml('Missing from resume (evidence gaps)',a.missingFromResume,'These terms were not clearly evidenced in the resume text. Confirm whether you have relevant experience before adding them.');
 html+=analysisSectionHtml('Potential skill gaps to confirm',a.likelySkillGaps,'These are hypotheses, not facts about your ability. Confirm or correct them before planning.');
 html+=analysisSectionHtml('Skills to improve',a.skillsToImprove);
 html+=analysisSectionHtml('Skills with insufficient evidence',a.skillsWithInsufficientEvidence);
 html+=analysisSectionHtml('Interview topics',a.interviewTopics);
 html+=analysisSectionHtml('Practice recommendations',a.practicePlan);
 html+=analysisSectionHtml('Suggested projects',a.recommendedProjects);
 html+=analysisSectionHtml('Resume improvements',a.resumeChanges);
 html+=analysisSectionHtml('Questions to clarify',a.questionsToClarify);
 html+='<p class="small-note">'+esc(disclaimer||'This is an AI-assisted comparison of the supplied text, not a hiring decision. Review every finding against your own experience.')+'</p>';
 return html;
}
async function analyzeJob(e){e.preventDefault();const msg=$('#jobAnalysisMsg'),result=$('#jobAnalysisResult'),body=$('#jobAnalysisBody'),btn=$('#jobAnalyzeBtn');if(!$('#jobText')?.value.trim()){msg.textContent='Import, paste or attach a job description and review the extracted text first.';msg.classList.add('error');return}msg.textContent='Comparing the job with your resume and saved profile…';msg.classList.remove('error');if(btn)btn.disabled=true;try{const d=await api('/job-analysis',{method:'POST',body:{title:$('#jobTitle').value,company:$('#jobCompany').value,sourceUrl:$('#jobUrl').value,jobDescription:$('#jobText').value,resumeText:$('#jobResumeText')?.value||''}});const analysis=d.skillGap?.analysis||{};state.lastJobAnalysis={analysis,title:$('#jobTitle').value,company:$('#jobCompany').value,jobDescription:$('#jobText').value,resumeText:$('#jobResumeText')?.value||'',jobDescriptionId:d.jobDescription?.id};body.innerHTML=renderJobAnalysisReport(analysis,d.disclaimer);result.classList.remove('hidden');msg.textContent='Analysis saved. Review the evidence labels and confirm potential skill gaps.';toast('Job description analyzed');wireJobPlanForm();result.scrollIntoView({behavior:'smooth',block:'start'})}catch(err){msg.textContent=err.message;msg.classList.add('error')}finally{if(btn)btn.disabled=false}}
function wireJobPlanForm(){const form=$('#jobPlanForm');if(!form)return;form.onsubmit=async e=>{e.preventDefault();const msg=$('#jobPlanMsg'),btn=$('#createJobPrepRoadmap'),last=state.lastJobAnalysis||{},a=last.analysis||{};let days=$('#jobPlanDuration')?.value==='custom'?Number($('#jobPlanCustomDays')?.value||30):Number($('#jobPlanDuration')?.value||30);days=Math.max(7,Math.min(365,Math.trunc(days||30)));const dailyHours=Number($('#jobPlanDailyHours')?.value||2);if(!Number.isFinite(dailyHours)||dailyHours<0.5||dailyHours>12){msg.textContent='Daily study time must be between 0.5 and 12 hours.';msg.classList.add('error');return}btn.disabled=true;msg.textContent='Building a plan around this role and the skill gaps you selected…';msg.classList.remove('error');const focus=Array.from(new Set([...(a.likelySkillGaps||[]).map(analysisItemText),...(a.skillsToImprove||[]).map(analysisItemText),...(a.missingFromResume||[]).map(analysisItemText),...(a.interviewTopics||[]).map(analysisItemText)].filter(Boolean))).slice(0,25);const style=$('#jobPlanStyle')?.value||'daily';try{const d=await api('/roadmaps',{method:'POST',body:{title:(last.title||'Target role')+' · '+days+'-day interview preparation',targetRole:last.title||'Target role',days,weeks:Math.ceil(days/7),weeklyHours:Math.max(1,Math.min(80,Math.round(dailyHours*7))),dailyHours,planType:style,focusTopics:focus,jobAnalysisContext:JSON.stringify({requiredSkills:a.requiredSkills||[],preferredSkills:a.preferredSkills||[],experienceRequirements:a.experienceRequirements||[],interviewTopics:a.interviewTopics||[],practicePlan:a.practicePlan||[],missingFromResume:a.missingFromResume||[],likelySkillGaps:a.likelySkillGaps||[]}).slice(0,10000),targetDate:new Date(Date.now()+days*86400000).toISOString().slice(0,10),useAI:true}});toast(d.message||'Personalized interview roadmap created');await renderPane('roadmap')}catch(err){msg.textContent=err.message;msg.classList.add('error')}finally{if($('#createJobPrepRoadmap'))$('#createJobPrepRoadmap').disabled=false}}}
async function startInterview(e){e.preventDefault();const msg=$('#interviewStartMsg'),btn=e.submitter,mode=$('#interviewMode').value;if(mode!=='text'&&!$('#interviewMediaConsent')?.checked){msg.textContent='Please read and accept the audio/video consent before starting a media interview.';msg.classList.add('error');return}if(btn)btn.disabled=true;msg.textContent='Preparing your first question…';try{const d=await api('/interviews',{method:'POST',body:{action:'start',interviewType:$('#interviewType').value,difficulty:$('#interviewDifficulty').value,targetRole:$('#interviewRole').value,title:$('#interviewTitle').value,mode,companyStyle:$('#interviewCompanyStyle').value,programmingLanguage:$('#interviewLanguage').value,durationMinutes:Number($('#interviewDuration').value),mediaConsent:mode!=='text'&&$('#interviewMediaConsent')?.checked===true}});state.activeInterviewId=Number(d.session.id);state.audioInterviewId=Number(d.session.id);toast('Interview session started');await renderPane(mode==='text'?'interviews':'audio-interview')}catch(err){msg.textContent=err.message;msg.classList.add('error')}finally{if(btn)btn.disabled=false}}
async function answerInterview(e){e.preventDefault();const msg=$('#interviewAnswerMsg'),btn=e.submitter;const d=await api('/interviews?id='+state.activeInterviewId);const session=d.session,turns=session&&session.turns||[],last=turns[turns.length-1];if(!last){msg.textContent='No pending question found.';return}if(btn)btn.disabled=true;msg.textContent='Evaluating your answer…';try{const r=await api('/interviews',{method:'POST',body:{action:'answer',sessionId:state.activeInterviewId,turnId:last.id,answer:$('#interviewAnswer').value}});toast('Feedback saved');await renderPane('interviews')}catch(err){msg.textContent=err.message;msg.classList.add('error')}finally{if(btn)btn.disabled=false}}
